use std::{env,fs,path::Path};
use wasmc::lib_tool_rust_consumer_sdk::native_build::NativePinnedFile;
use wasmc::lib_tool_rust_consumer_sdk::native_build::host::{compile_host_canonical_source,HostContract,HostContractPair};
fn sha(b:&[u8])->String{wasmc::self_bundle::hex(&wasmc::self_bundle::sha256(b))}
fn contract(dir:&Path,selection:&[&str])->HostContract{let f=|n|fs::read(dir.join(n)).unwrap();let(wit,execution_abi,provider_contract,binding)=(f("lib.wit"),f("execution-abi.json"),f("provider-contract.json"),f("binding.json"));HostContract{schema:"wasmc.canonical-host-contract/v1".into(),wit_sha256:sha(&wit),execution_abi_sha256:sha(&execution_abi),provider_contract_sha256:sha(&provider_contract),binding_sha256:sha(&binding),wit,execution_abi,provider_contract,binding,selected_operations:vec![],operation_selection:Some(selection.iter().map(|x|x.to_string()).collect())}}
fn main(){let a:Vec<_>=env::args().collect();let base=Path::new(&a[1]);let f=base.join("examples/current/canonical-checked-results-v2");let kit=base.join("lib-releases/wasmc-json/0.0.7");let root=kit.join("root");let hostroot=kit.join("host");let host=HostContractPair{entry:contract(&hostroot.join("entry"),&[]),operations:contract(&hostroot.join("operations"),&["service.invoke","table.response-len","table.response-drop"])};let source=fs::read_to_string(f.join("ordinary.wasmc")).unwrap();let pin=sha(&fs::read(root.join("lib.json")).unwrap());let app=compile_host_canonical_source(&source,&root,&pin,&host,17).expect("native compilation");let pinned=|p:&Path|NativePinnedFile{path:p.into(),sha256:sha(&fs::read(p).unwrap())};let sealed=base.join("native-sealed-parity-output");let merge=env::var("WASMC_WASM_MERGE").expect("WASMC_WASM_MERGE");app.seal(&host,&pinned(&f.join("raw-transfer.wasm")),&pinned(&base.join("current/lib_core.wasm")),&pinned(Path::new(&merge)),&sealed).expect("native sealing");println!("native_sealed=true");}
